package com.orderflow.notification.provider;public record SendResult(Result result,String failureCode){public enum Result{SUCCESS,TEMPORARY_FAILURE,PERMANENT_FAILURE}public static SendResult success(){return new SendResult(Result.SUCCESS,null);}public static SendResult temporary(String c){return new SendResult(Result.TEMPORARY_FAILURE,c);}public static SendResult permanent(String c){return new SendResult(Result.PERMANENT_FAILURE,c);}}
